def clean(df):
    df = df.drop_duplicates()
    df['species'] = df['species'].str.strip()
    df['species'] = df['species'].replace('Chinstarp', 'Chinstrap')
    return df

def answer(df):
    adelie = df[df['species'] == 'Adelie']
    return adelie.groupby('island')['bill_length_mm'].mean().to_dict()
